import {HARMONICS} from './voice-dsp.mjs';
import {PARTICLES} from './mouth-dsp.mjs';
class PlaneMorph extends AudioWorkletProcessor{
 constructor(options){super();this.target=options.processorOptions.model;this.pitch=this.target.pitch;this.voicing=this.target.voicing;this.amps=Float64Array.from(this.target.amplitudes);this.freq=Float64Array.from(this.target.frequencies);this.phase=0;this.fade=0;this.energy=.0324;this.gain=1;this.sin=new Float64Array(PARTICLES);this.cos=new Float64Array(PARTICLES);for(let v=0;v<PARTICLES;v++){this.sin[v]=Math.sin(v*2.39996323);this.cos[v]=Math.cos(v*2.39996323)}this.port.onmessage=e=>{if(e.data.model)this.target=e.data.model};this.noise=new Float32Array(128)}
 process(inputs,outputs){const channels=outputs[0],out=channels[0],m=this.target;if(this.noise.length!==out.length)this.noise=new Float32Array(out.length);const noise=this.noise;noise.fill(0);if(m.voicing<.9999||this.voicing<.9999){const scale=.18*Math.sqrt(2/PARTICLES);for(let v=0;v<PARTICLES;v++){this.freq[v]+=(m.frequencies[v]-this.freq[v])*.15;const angle=2*Math.PI*Math.min(sampleRate*.46,Math.max(25,this.freq[v]))/sampleRate,dc=Math.cos(angle),ds=Math.sin(angle);let s=this.sin[v],c=this.cos[v];for(let j=0;j<out.length;j++){noise[j]+=s*scale;const next=s*dc+c*ds;c=c*dc-s*ds;s=next}const norm=1/Math.hypot(s,c);this.sin[v]=s*norm;this.cos[v]=c*norm}let energy=0;for(const v of noise)energy+=v*v;this.energy=.97*this.energy+.03*energy/out.length}
 for(let h=0;h<HARMONICS;h++)this.amps[h]+=(m.amplitudes[h]-this.amps[h])*.15;
 for(let j=0;j<out.length;j++){this.pitch+=(m.pitch-this.pitch)*.002;this.voicing+=(m.voicing-this.voicing)*.002;this.phase=(this.phase+2*Math.PI*this.pitch/sampleRate)%(2*Math.PI);let tone=0;if(this.voicing>.00001)for(let h=1;h<=HARMONICS;h++)if(h*this.pitch<sampleRate*.46)tone+=this.amps[h-1]*Math.sin(h*this.phase-Math.PI*h*(h-1)/HARMONICS);this.gain+=(Math.min(2,.18/Math.sqrt(this.energy+1e-8))-this.gain)*.001;this.fade=Math.min(1,this.fade+1/(sampleRate*.04));out[j]=Math.tanh(tone*Math.sqrt(this.voicing)+noise[j]*this.gain*Math.sqrt(Math.max(0,1-this.voicing)))*this.fade}for(let c=1;c<channels.length;c++)channels[c].set(out);return true}
}registerProcessor('plane-morph',PlaneMorph);
